class Solution {
public:
    int totalFruit(vector<int>& fruits) {
        map<int, int> basket;
        int l = 0, best = 0;
        for (int r = 0; r < (int)fruits.size(); r++) {
            basket[fruits[r]]++;
            while (basket.size() > 2) {
                if (--basket[fruits[l]] == 0) basket.erase(fruits[l]);
                l++;
            }
            best = max(best, r - l + 1);
        }
        return best;
    }
};
